fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // We use 1-based indexing for k, and assume 1 <= k < list.len()
    assert!(k >= 1 && k < list.len(), "k must satisfy 1 <= k < list.len()");
    
    // Pre-allocate the result with length list.len() - 1
    let n = list.len();
    let mut new_list = Vec::with_capacity(n - 1);
    
    // Copy the prefix before the k-th element (in 0-based: indices 0..k-1)
    new_list.extend_from_slice(&list[..(k - 1)]);
    
    // Copy the suffix after the k-th element (in 0-based: indices k..n-1)
    new_list.extend_from_slice(&list[k..]);
    
    new_list
}

